  // Global System Runtime Logic Core
  window.onerror = function(message, source, lineno) {
    const stream = document.getElementById('terminalStream');
    if (stream) {
      stream.innerHTML += `<div class="terminal-line line-fatal">[ENGINE HANDSHAKE ERROR] Line ${lineno}: ${message}</div>`;
      stream.scrollTop = stream.scrollHeight;
    }
    return true; 
  };

  document.getElementById('acceptLegalBtn').addEventListener('click', () => {
    document.getElementById('legalOverlay').style.display = 'none';
    document.body.classList.add('unlocked');
    appendStreamLog("[SYSTEM ENGINE ONLINE]: Security framework authenticated. Standby for vector configuration execution.", "line-info");
  });

  let variableCounter = 1;
  let executionActive = false;
  let auditedValidTargets = []; 
  let targetPermutationQueue = [];
  let totalCalculatedPermutationsCount = 0;
  let deadEntriesCount = 0;
  let configSnapshot = {};

  window.onload = function() {
    function tickClock() { 
      const clk = document.getElementById('runtimeClock');
      if (clk) clk.textContent = new Date().toUTCString(); 
    }
    setInterval(tickClock, 1000); tickClock();
  };

  document.getElementById('appendVarNode').addEventListener('click', () => {
    variableCounter++;
    const node = document.createElement('div');
    node.className = 'variable-node';
    node.innerHTML = `
      <button class="remove-node-btn" onclick="this.parentNode.remove()"><i class="fa-solid fa-xmark"></i></button>
      <div class="grid-var">
        <div class="form-group" style="margin:0;">
          <label>Variable Token</label>
          <input type="text" class="v-token-name" value="variable${variableCounter}" />
        </div>
        <div class="form-group" style="margin:0;">
          <label>Mutation Strategy</label>
          <select class="v-strategy" onchange="switchStrategyInterface(this)">
            <option value="numeric">Numbers Sequence</option>
            <option value="alpha">Letters Array</option>
            <option value="custom-list">Space Separated Array</option>
          </select>
        </div>
        <div class="v-runtime-inputs" style="width: 100%;">
          <div class="grid-3" style="margin:0;">
            <div><label>Min</label><input type="number" class="n-min" value="1"></div>
            <div><label>Max</label><input type="number" class="n-max" value="10"></div>
            <div><label>Pad</label><input type="number" class="n-pad" value="0"></div>
          </div>
        </div>
      </div>
    `;
    document.getElementById('variable-pipeline').appendChild(node);
  });

  function switchStrategyInterface(dropdown) {
    const container = dropdown.parentNode.parentNode.querySelector('.v-runtime-inputs');
    if (dropdown.value === 'numeric') {
      container.innerHTML = `<div class="grid-3" style="margin:0;"><div><label>Min</label><input type="number" class="n-min" value="1"></div><div><label>Max</label><input type="number" class="n-max" value="10"></div><div><label>Pad</label><input type="number" class="n-pad" value="0"></div></div>`;
    } else if (dropdown.value === 'alpha') {
      container.innerHTML = `<div class="grid-3" style="margin:0;"><div><label>Start</label><input type="text" class="a-start" value="a" maxlength="1"></div><div><label>End</label><input type="text" class="a-end" value="z" maxlength="1"></div></div>`;
    } else if (dropdown.value === 'custom-list') {
      container.innerHTML = `<div style="width: 100%;"><label>Space-Separated Values</label><textarea class="c-list" placeholder="A B C 1 2 3" style="min-height: 38px; padding: 8px 12px;"></textarea></div>`;
    }
  }

  function runVerificationProbe(target, assetType) {
    return new Promise((res) => {
      if (assetType === 'image') {
        const probe = new Image();
        probe.onload = () => res({ url: target.stringUrl, status: true, w: probe.naturalWidth, h: probe.naturalHeight, vars: target.parameters });
        probe.onerror = () => res({ url: target.stringUrl, status: false });
        probe.src = target.stringUrl;
      } else {
        fetch(target.stringUrl, { method: 'GET', mode: 'cors' })
          .then(r => { res({ url: target.stringUrl, status: r.ok, w: 'HTML', h: 'DOC', vars: target.parameters }); })
          .catch(() => { res({ url: target.stringUrl, status: false }); });
      }
    });
  }

  function appendStreamLog(text, styleSignature) {
    const consoleContainer = document.getElementById('terminalStream');
    if (consoleContainer) {
      const row = document.createElement('div');
      row.className = `terminal-line ${styleSignature}`;
      row.textContent = `[${new Date().toLocaleTimeString()}] ${text}`;
      consoleContainer.appendChild(row);
      consoleContainer.scrollTop = consoleContainer.scrollHeight;
    }
  }

  function crossProductPermutations(arrays) {
    let result = [{}];
    for (let i = 0; i < arrays.length; i++) {
      const context = arrays[i]; const bucket = [];
      for (let j = 0; j < result.length; j++) {
        const current = result[j];
        for (let k = 0; k < context.elements.length; k++) {
          const obj = Object.assign({}, current);
          obj[context.name] = context.elements[k];
          bucket.push(obj);
        }
      }
      result = bucket;
    }
    return result;
  }

  const delayResolution = (ms) => new Promise(res => setTimeout(res, ms));

  document.getElementById('fireEngineAction').addEventListener('click', async () => {
    if (executionActive) {
      executionActive = false;
      document.getElementById('fireEngineAction').innerHTML = '<i class="fa-solid fa-play"></i> Resume v1';
      document.getElementById('runtimeStatus').textContent = 'System Halted';
      return;
    }

    const patternString = document.getElementById('targetUrl').value;
    const widthFilterValue = parseInt(document.getElementById('ignoreWidth').value) || -1;
    const operationalIntervalDelay = parseInt(document.getElementById('stepDelay').value) || 0;
    const projectName = document.getElementById('projectName').value.trim() || 'v1_Audit';
    const targetAssetType = document.getElementById('assetTypeSelector').value;

    if (targetPermutationQueue.length === 0) {
      const configurationNodes = document.querySelectorAll('.variable-node');
      const pipelineConfigMap = Array.from(configurationNodes).map(node => {
        const tokenLabel = node.querySelector('.v-token-name').value.replace(/[{}]/g, '');
        const configurationStrategy = node.querySelector('.v-strategy').value;
        let set = [];

        if (configurationStrategy === 'numeric') {
          const min = parseInt(node.querySelector('.n-min').value);
          const max = parseInt(node.querySelector('.n-max').value);
          const pad = parseInt(node.querySelector('.n-pad').value) || 0;
          for (let i = min; i <= max; i++) set.push(pad > 0 ? i.toString().padStart(pad, '0') : i.toString());
        } else if (configurationStrategy === 'alpha') {
          const start = node.querySelector('.a-start').value.charCodeAt(0);
          const end = node.querySelector('.a-end').value.charCodeAt(0);
          for (let i = start; i <= end; i++) set.push(String.fromCharCode(i));
        } else if (configurationStrategy === 'custom-list') {
          const text = node.querySelector('.c-list').value.trim();
          set = text.split(/\s+/);
        }
        return { name: tokenLabel, elements: set, strategy: configurationStrategy };
      });

      for (let i = 0; i < pipelineConfigMap.length; i++) {
        if (!patternString.includes(`{${pipelineConfigMap[i].name}}`)) {
          alert(`Blueprint layout is missing expected variable injection token: {${pipelineConfigMap[i].name}}`); return;
        }
      }

      configSnapshot = { projectName, patternString, ignoreWidth: widthFilterValue, delay: operationalIntervalDelay, type: targetAssetType, variables: pipelineConfigMap };

      const generatedPermutationsMatrix = crossProductPermutations(pipelineConfigMap);
      targetPermutationQueue = generatedPermutationsMatrix.map(combo => {
        let url = patternString; let tokensUsed = {};
        for (const [key, value] of Object.entries(combo)) {
          url = url.replace(new RegExp(`{${key}}`, 'g'), value);
          tokensUsed[key] = value;
        }
        return { stringUrl: url, parameters: tokensUsed };
      });

      totalCalculatedPermutationsCount = targetPermutationQueue.length;
      deadEntriesCount = 0;
      document.getElementById('progressBarWrapper').style.display = 'block';
      appendStreamLog(`[v1 COCHLEA]: Queue synchronized. Compiled ${totalCalculatedPermutationsCount} test routines.`, 'line-info');
    }

    executionActive = true;
    document.getElementById('fireEngineAction').innerHTML = '<i class="fa-solid fa-pause"></i> Pause Engine';
    document.getElementById('exportPdfReport').disabled = true;

    const chunkSize = 15; 

    while (targetPermutationQueue.length > 0 && executionActive) {
      document.getElementById('runtimeStatus').textContent = `Tracing matrix logs (${targetPermutationQueue.length} left)`;
      
      const currentChunk = targetPermutationQueue.splice(0, chunkSize);
      const batchPromises = currentChunk.map(target => runVerificationProbe(target, targetAssetType));
      const chunkResults = await Promise.all(batchPromises);

      for (let i = 0; i < chunkResults.length; i++) {
        const check = chunkResults[i];
        if (check.status) {
          if (targetAssetType === 'image' && check.w === widthFilterValue) {
            deadEntriesCount++;
            appendStreamLog(`[FILTER EXCLUDED]: Canvas boundaries matched default template signature (${check.w}px) -> ${check.url}`, 'line-warn');
          } else {
            auditedValidTargets.push(check);
            const dimStr = (check.w === 'HTML') ? "DOC" : `${check.w}x${check.h}px`;
            appendStreamLog(`[✓ ENDPOINT ACCESSIBLE] [${dimStr}] -> ${check.url}`, 'line-success');
            document.getElementById('discoveredCount').textContent = `${auditedValidTargets.length} Validated`;
          }
        } else {
          deadEntriesCount++;
          appendStreamLog(`[x 404 RES DISCONNECT] -> ${check.url}`, 'line-error');
        }
      }

      const operationsFinished = totalCalculatedPermutationsCount - targetPermutationQueue.length;
      document.getElementById('progressBarFill').style.width = `${(operationsFinished / totalCalculatedPermutationsCount) * 100}%`;

      await delayResolution(operationalIntervalDelay > 0 ? operationalIntervalDelay : 10);
    }

    if (targetPermutationQueue.length === 0) {
      executionActive = false;
      document.getElementById('fireEngineAction').innerHTML = '<i class="fa-solid fa-play"></i> Run Engine';
      document.getElementById('runtimeStatus').textContent = 'Execution Map Complete.';
      document.getElementById('progressBarFill').style.width = '100%';
      if (auditedValidTargets.length > 0) document.getElementById('exportPdfReport').removeAttribute('disabled');
    }
  });

  document.getElementById('wipeLogsAction').addEventListener('click', () => {
    executionActive = false; targetPermutationQueue = []; auditedValidTargets = [];
    totalCalculatedPermutationsCount = 0; deadEntriesCount = 0;
    document.getElementById('terminalStream').innerHTML = '';
    document.getElementById('fireEngineAction').innerHTML = '<i class="fa-solid fa-play"></i> Run Engine';
    document.getElementById('discoveredCount').textContent = '0 Validated';
    document.getElementById('runtimeStatus').textContent = 'Idling';
    document.getElementById('progressBarWrapper').style.display = 'none';
    document.getElementById('exportPdfReport').setAttribute('disabled', 'true');
  });

  document.getElementById('exportPdfReport').addEventListener('click', () => {
    const { jsPDF } = window.jspdf;
    const pdf = new jsPDF({ orientation: 'p', unit: 'mm', format: 'a4' });
    const localTimestamp = new Date().toUTCString();
    const margin = 15;
    let currentY = 0;

function drawProfessionalHeader(doc) {
  // Full Bleed Navy Header Bar Background
  doc.setFillColor(96, 125, 139); 
  doc.rect(0, 0, 210, 28, "F");
  
  // Bottom Orange Accent Band
  doc.setFillColor(249, 115, 22); 
  doc.rect(0, 28, 210, 2, "F");

  // === REAL IMAGE LOGO PLACEMENT ===
  // Replace this placeholder with your real Base64 image string sequence
  const logoBase64 = "data:image/png;base64,"; 
  
  try {
    // doc.addImage(imageData, format, x, y, width, height)
    // Placed at X: 15mm, Y: 5mm, scaled to 18mm wide by 18mm high
    doc.addImage(logoBase64, 'PNG', 15, 5, 18, 18);
  } catch (imageError) {
    // Fallback vector bounding wireframe if the string string is broken or corrupt
    doc.setDrawColor(249, 115, 22); doc.setLineWidth(0.5);
    doc.rect(15, 5, 18, 18);
  }

  // Shifted typography to the right (X: 38) to make room for your logo image canvas
  doc.setFont("Helvetica", "bold"); doc.setFontSize(22); doc.setTextColor(255, 255, 255);
  doc.text("CRAB", 38, 18);

  doc.setFont("Helvetica", "normal"); doc.setFontSize(8); doc.setTextColor(200, 200, 200);
  doc.text(" Website : https://the27links.in/tools/crab  || E-Mail : the27linksofficial@gmail.com", 38, 22);
  
  doc.setFont("Helvetica", "normal"); doc.setFontSize(10); doc.setTextColor(200, 200, 200);
  doc.text("ASSET AUDIT COMPLIANCE CLIENT", 65, 17.5);
  
  doc.setFont("Courier", "normal"); doc.setFontSize(8); doc.setTextColor(150, 150, 150);
  doc.text("SECURE AUDIT RECORD", 155, 17.5);
}

    function addFooter(doc, pageNum) {
      doc.setDrawColor(200, 200, 200); doc.setLineWidth(0.2); doc.line(15, 282, 195, 282);
      doc.setFont("Helvetica", "normal"); doc.setFontSize(8); doc.setTextColor(100, 116, 139);
      doc.text(`Crab| Powered By The27LINKS. || Signature Time: ${localTimestamp}`, margin, 287);
      doc.text(`Page ${pageNum}`, 185, 287);
    }

    // --- PAGE 1: COVER DATA & CONFIGS ---
    drawProfessionalHeader(pdf);
    let curY = 45;
    pdf.setFont("Helvetica", "bold"); pdf.setFontSize(18); pdf.setTextColor(15, 23, 42);
    pdf.text(configSnapshot.projectName.toUpperCase(), 15, curY);
    
    curY += 8;
    pdf.setFont("Helvetica", "normal"); pdf.setFontSize(10); pdf.setTextColor(50, 50, 50);
    pdf.text("Final Asset Discovery Matrix Audit Ledger Log", 15, curY);

    curY += 12;
    pdf.setFillColor(248, 250, 252); pdf.setDrawColor(226, 232, 240); pdf.rect(15, curY, 180, 54, "FD");
    pdf.setFont("Helvetica", "bold"); pdf.setFontSize(10); pdf.setTextColor(15, 23, 42);
    pdf.text("System Execution Parameters Logged:", 20, curY + 8);
    
    pdf.setFont("Courier", "normal"); pdf.setFontSize(9); pdf.setTextColor(50, 50, 50);
    pdf.text(`Target Blueprint : ${configSnapshot.patternString}`, 20, curY + 16);
    pdf.text(`Asset Probe Mode : ${configSnapshot.type.toUpperCase()}`, 20, curY + 22);
    pdf.text(`Ignore Width     : ${configSnapshot.ignoreWidth === -1 ? 'None' : configSnapshot.ignoreWidth + 'px'}`, 20, curY + 28);
    pdf.text(`Throttle Delay   : ${configSnapshot.delay}ms`, 20, curY + 34);

    let varY = curY + 42;
    pdf.setFont("Helvetica", "bold"); pdf.setFontSize(9); pdf.setTextColor(15, 23, 42);
    pdf.text("Configured Token Variables Pipeline:", 20, varY);
    pdf.setFont("Courier", "normal"); pdf.setFontSize(8.5); pdf.setTextColor(50, 50, 50);
    
    for(let j=0; j<configSnapshot.variables.length; j++) {
      let v = configSnapshot.variables[j]; varY += 5;
      pdf.text(`- {${v.name}} : System Strategy [${v.strategy}] -> Generated ${v.elements.length} variations entries.`, 25, varY);
    }

    curY = varY + 15;
    pdf.setFont("Helvetica", "bold"); pdf.setFontSize(11); pdf.setTextColor(15, 23, 42);
    pdf.text("Execution Metrics Ledger Summary", 15, curY);
    pdf.setDrawColor(249, 115, 22); pdf.setLineWidth(0.5); pdf.line(15, curY + 2, 48, curY + 2);

    curY += 12;
    pdf.setFont("Helvetica", "bold"); pdf.setFontSize(10); pdf.setTextColor(100, 116, 139);
    pdf.text("PERMUTATIONS RUN", 15, curY); pdf.text("VERIFIED SUCCESS", 85, curY); pdf.text("DROPPED / 404 CODES", 140, curY);

    curY += 8;
    pdf.setFontSize(16); pdf.setTextColor(30, 64, 175); pdf.text(`${totalCalculatedPermutationsCount}`, 15, curY);
    pdf.setTextColor(16, 185, 129); pdf.text(`${auditedValidTargets.length}`, 85, curY);
    pdf.setTextColor(244, 63, 94); pdf.text(`${deadEntriesCount}`, 140, curY);

    pdf.setFillColor(254, 242, 242); pdf.setDrawColor(251, 113, 133); pdf.rect(15, 255, 180, 18, "FD");
    pdf.setFont("Helvetica", "bold"); pdf.setFontSize(8); pdf.setTextColor(159, 18, 57);
    pdf.text("PLATFORM TERMS OF SERVICE & LIABILITY POLICY LIMITATIONS NOTICE", 20, 261);
    pdf.setFont("Helvetica", "normal"); pdf.setFontSize(7.5); pdf.setTextColor(112, 26, 40);
    pdf.text("This index log report has been generated programmatically via secure network routing protocols on The27LINKS domain dashboard framework.", 20, 266);
    pdf.text("All operations data, target links context mapping, and vector configurations remain fully within the absolute liability tracking of the user.", 20, 270);

    addFooter(pdf, 1);

    // --- PAGE 2+: ROWS DATA MATRIX ---
    pdf.addPage(); let pageNum = 2; drawProfessionalHeader(pdf); currentY = 45;
    pdf.setFont("Helvetica", "bold"); pdf.setFontSize(14); pdf.setTextColor(15, 23, 42);
    pdf.text("Validated Endpoints Ledger Index", 15, currentY);
    
    currentY += 8;
    pdf.setFillColor(15, 23, 42); pdf.rect(15, currentY, 180, 8, "F");
    pdf.setFontSize(9); pdf.setTextColor(255, 255, 255);
    pdf.text("IDX", 18, currentY + 5.5); pdf.text("MUTATOR BOUNDS VARIABLE PERMUTATIONS", 30, currentY + 5.5); pdf.text("VERIFIED ACCESS DIRECTORY URL LOCATION", 100, currentY + 5.5);
    
    currentY += 8; let isZebra = false;

    for (let i = 0; i < auditedValidTargets.length; i++) {
      const asset = auditedValidTargets[i];
      if (currentY > 270) {
        addFooter(pdf, pageNum); pdf.addPage(); pageNum++; drawProfessionalHeader(pdf); currentY = 40;
        pdf.setFillColor(15, 23, 42); pdf.rect(15, currentY, 180, 8, "F");
        pdf.setFont("Helvetica", "bold"); pdf.setFontSize(9); pdf.setTextColor(255, 255, 255);
        pdf.text("IDX", 18, currentY + 5.5); pdf.text("MUTATOR BOUNDS VARIABLE PERMUTATIONS", 30, currentY + 5.5); pdf.text("VERIFIED ACCESS DIRECTORY URL LOCATION", 100, currentY + 5.5);
        currentY += 8;
      }

      if (isZebra) { pdf.setFillColor(248, 250, 252); pdf.rect(15, currentY, 180, 7, "F"); }
      isZebra = !isZebra;

      pdf.setFont("Helvetica", "bold"); pdf.setFontSize(8.5); pdf.setTextColor(15, 23, 42);
      pdf.text(String(i + 1).padStart(3, '0'), 18, currentY + 5);

      let varString = "";
      for (const [key, value] of Object.entries(asset.vars)) { varString += key + ":" + value + " "; }
      pdf.setFont("Helvetica", "normal"); pdf.setFontSize(8); pdf.setTextColor(70, 70, 70);
      pdf.text(varString.trim(), 30, currentY + 5);

      pdf.setFont("Courier", "normal"); pdf.setFontSize(8); pdf.setTextColor(100, 100, 100);
      let urlPrint = asset.url;
      if (urlPrint.length > 52) urlPrint = urlPrint.substring(0, 50) + "...";
      pdf.text(urlPrint, 100, currentY + 5);

      currentY += 7;
    }

    addFooter(pdf, pageNum);
    const cleanProjectName = configSnapshot.projectName.replace(/[^a-zA-Z0-9_-]/g, "_");
    pdf.save(cleanProjectName + "_Matrix_Ledger_" + Date.now() + ".pdf");
    appendStreamLog("[EXPORT METRICS SUCCESSFUL]: PDF index report finalized safely and initialized local storage saving routines.", "line-success");
  });
